<!-- Interactive Filter Script -->
<script>
    (function() {
      const filterBtns = document.querySelectorAll('#categoryFilterContainer .filter-btn');
      const serviceCards = document.querySelectorAll('#servicesCatalogGrid .service-card');
      const visibleCountEl = document.getElementById('visibleCount');

      filterBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          // Reset styles
          filterBtns.forEach(b => {
            b.classList.remove('bg-safety-emerald', 'text-text-primary');
            b.classList.add('bg-regulatory-slate-800', 'text-text-secondary');
          });

          // Active style
          btn.classList.remove('bg-regulatory-slate-800', 'text-text-secondary');
          btn.classList.add('bg-safety-emerald', 'text-text-primary');

          const filterVal = btn.getAttribute('data-filter');
          let count = 0;

          serviceCards.forEach(card => {
            const cat = card.getAttribute('data-cat');
            if (filterVal === 'all' || cat === filterVal) {
              card.style.display = 'flex';
              count++;
            } else {
              card.style.display = 'none';
            }
          });

          if(visibleCountEl) {
            visibleCountEl.textContent = count;
          }
        });
      });
    })();
  </script>
